-- Migration: as duas tabelas oficiais da classificação tributária IBS/CBS
--            `cst_ibs_cbs` (18 linhas) e `cclass_trib` (164 linhas)
--
-- ══════════════════════════════════════════════════════════════════════════
-- FONTE — e ela é PRIMÁRIA, o que muda o peso deste arquivo
-- ══════════════════════════════════════════════════════════════════════════
-- Arquivo oficial `cClassTrib 2026-06-22.xlsx`, do Portal DF-e SVRS, extraído
-- por LEITURA DIRETA DO XLSX — sem transcrição, sem digitação, sem resumo de
-- terceiro. É a fonte que a ressalva de `cascata-lucro-real.md` pedia:
-- *"quem for implementar lê a NT no Portal Nacional da NF-e, não este resumo"*.
--
-- O `cClassTrib` é o vínculo entre o item e o dispositivo da LC 214/2025 que lhe
-- dá o tratamento tributário. CÓDIGO ERRADO SIGNIFICA APURAÇÃO ERRADA, não campo
-- em branco — e o par (CST, cClassTrib) incompatível é rejeitado pela SEFAZ.
--
-- ══════════════════════════════════════════════════════════════════════════
-- ORDEM DE APLICAÇÃO — esta migração cria COLUNA/TABELA que código novo LÊ
-- ══════════════════════════════════════════════════════════════════════════
-- `migration-delivery.md`: tabela que o código novo consulta → APLICAR ANTES OU
-- JUNTO do merge. Mergear antes deixa a tela de produto consultando tabela
-- inexistente. E o default de toda migração é PENDENTE: merge não aplica nada,
-- build verde não prova schema. A verificação é a consulta ao `information_schema`
-- no fim deste arquivo, mais o `NOTIFY pgrst`.
--
-- ══════════════════════════════════════════════════════════════════════════
-- AS DUAS METADES DA MESMA INFORMAÇÃO, e por que são duas tabelas
-- ══════════════════════════════════════════════════════════════════════════
--   `cst_ibs_cbs`  → o CST diz QUAIS GRUPOS a operação leva (`ind_g_red`,
--                    `ind_g_dif`, …). São 18, e o `ind_g_red` liga em TRÊS:
--                    011, 200 e 515.
--   `cclass_trib`  → o código diz QUAIS PERCENTUAIS (`p_red_ibs`, `p_red_cbs`)
--                    e a que dispositivo da LC ele se prende.
--
-- Procurar o indicador no cClassTrib, ou o percentual no CST, é inferir em vez
-- de ler — `regime-e-segmento-determinam-a-construcao.md`.
--
-- ══════════════════════════════════════════════════════════════════════════
-- TRÊS DECISÕES DE DESENHO, cada uma com a razão no ponto de declaração
-- ══════════════════════════════════════════════════════════════════════════
--
-- 1. A CHAVE É O PAR (cst, codigo), NÃO o código sozinho.
--    Medido: `codigo` é único nas 164 linhas desta publicação. NÃO usamos isso
--    como chave, porque é propriedade DO DADO DE 2026-06-22, não do domínio: uma
--    publicação futura que reaproveite um código sob outro CST faria a carga
--    falhar. `razao-longe-da-restricao.md` — restrição precisa de razão, e
--    "medi uma vez e deu único" não é razão suficiente para virar chave.
--
-- 2. VIGÊNCIA NÃO É VERSÃO, e as duas convivem em colunas separadas.
--    `d_ini_vig`/`d_fim_vig` dizem quando o código vale NO MUNDO;
--    `source_published_at` diz quando A NOSSA CÓPIA foi publicada. Um código é
--    revogado sem a tabela mudar, e a tabela muda sem vigência nenhuma mudar.
--    NÃO há tabela de versões: hoje existe UMA publicação, e `source_published_at`
--    já responde as duas perguntas ("de qual publicação esta linha veio" e, por
--    `select distinct`, "qual publicação o sistema tem"). Quando duas publicações
--    conviverem, a coluna já é a chave do agrupamento e a tabela de versões nasce
--    dela, sem migrar dado.
--
-- 3. `d_fim_vig` NULÁVEL E SEM DEFAULT — `ausente-vs-falso.md`. NULL é "sem prazo
--    de fim"; qualquer default afirmaria um fim que a lei não deu.
--    Os percentuais `p_red_ibs`/`p_red_cbs`, ao contrário, são NOT NULL: as 164
--    linhas trazem valor, e o ZERO ali é APURADO — "sem redução" é afirmação do
--    fisco, não ausência de dado.
--
-- ══════════════════════════════════════════════════════════════════════════
-- O QUE A CARGA TRAZ, medido sobre o arquivo oficial
-- ══════════════════════════════════════════════════════════════════════════
--   cst_ibs_cbs .............. 18 linhas
--   cclass_trib .............. 164 linhas, 18 CST distintos
--   `d_ini_vig` .............. 2026-01-01 em 164 de 164
--   `d_fim_vig` preenchido ... 3 — 220001, 220002 e 220003, todos do CST 220,
--                              e nos três o FIM É IGUAL AO INÍCIO (2026-01-01).
--                              Está carregado como o arquivo traz. NÃO foi
--                              interpretado o que isso significa.
--   com redução > 0 .......... 59
--   valores de redução ....... 30, 40, 50, 60, 70, 80, 100 — exatamente as sete
--                              faixas do Select original do produto. A lista não
--                              era leitura da lei: era TRANSCRIÇÃO DESTA TABELA.
--                              Ver `razao-longe-da-restricao.md`.
--   divergência IBS × CBS .... 1 linha — `200025` (educação, ProUni) tem
--                              p_red_ibs = 60 e p_red_cbs = 100. É por isso que
--                              são DUAS colunas, e não uma.
--
-- ══════════════════════════════════════════════════════════════════════════
-- ESCOPO — o que este arquivo NÃO faz
-- ══════════════════════════════════════════════════════════════════════════
-- Nenhum DROP, nenhum ALTER em tabela existente, nenhum UPDATE de dado de
-- tenant. Só duas tabelas novas, de REFERÊNCIA (sem `tenant_id`), com RLS de
-- leitura pública no mesmo padrão de `ncm_codes` (`ncm_read`: SELECT, USING true).
-- As colunas do produto ficam na migração seguinte.

BEGIN;

-- ─────────────────────────────────────────────────────────────────────────
-- 1. CST do IBS/CBS — 18 códigos
-- ─────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS cst_ibs_cbs (
  cst                     text PRIMARY KEY,
  descricao               text        NOT NULL,
  -- Os oito indicadores de grupo da NT. 0/1 no arquivo oficial; aqui boolean,
  -- porque `false` é afirmação do fisco ("este grupo não se aplica"), não lacuna.
  ind_gibscbs             boolean     NOT NULL,
  ind_gibscbs_mono        boolean     NOT NULL,
  ind_gred                boolean     NOT NULL,
  ind_gdif                boolean     NOT NULL,
  ind_gtransf_cred        boolean     NOT NULL,
  ind_gcred_pres_ibszfm   boolean     NOT NULL,
  ind_gajuste_compet      boolean     NOT NULL,
  ind_redutor_bc          boolean     NOT NULL,
  search_normalized       text        NOT NULL,
  source_published_at     date        NOT NULL
);

COMMENT ON TABLE cst_ibs_cbs IS
  'CST do IBS/CBS — tabela de REFERÊNCIA, carregada do arquivo oficial cClassTrib do Portal DF-e SVRS. Sem tenant_id: é a mesma para todos. Os indicadores dizem quais GRUPOS a operação leva na NF-e; os PERCENTUAIS ficam em cclass_trib.';
COMMENT ON COLUMN cst_ibs_cbs.ind_gred IS
  'Indica se a operação leva o grupo gRed da NT 2025.002. Liga em TRÊS CST: 011, 200 e 515. O indicador é do CST; os percentuais de redução são do cClassTrib.';
COMMENT ON COLUMN cst_ibs_cbs.source_published_at IS
  'Data de publicação do arquivo oficial de onde esta linha veio. NÃO é vigência — vigência do código é d_ini_vig/d_fim_vig em cclass_trib.';

-- ─────────────────────────────────────────────────────────────────────────
-- 2. cClassTrib — 164 códigos
-- ─────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS cclass_trib (
  cst                     text        NOT NULL REFERENCES cst_ibs_cbs(cst),
  codigo                  text        NOT NULL,
  nome                    text        NOT NULL,
  descricao               text        NOT NULL,
  -- Texto do dispositivo. NULL quando o arquivo oficial não traz.
  lc_redacao              text,
  lc_214_25               text,
  regulamento_cbs         text,
  regulamento_ibs         text,
  tipo_aliquota           text        NOT NULL,
  -- Percentuais de REDUÇÃO, inteiros em [0, 100], na mesma unidade da tela e do
  -- banco (R4 de `cascata-lucro-real.md`): efetiva = original × (1 − pct/100).
  -- NOT NULL porque as 164 linhas trazem valor e o ZERO é apurado.
  -- DOIS campos, não um: o 200025 tem 60 no IBS e 100 no CBS.
  p_red_ibs               numeric     NOT NULL,
  p_red_cbs               numeric     NOT NULL,
  ind_g_trib_regular      boolean     NOT NULL,
  ind_g_cred_pres_oper    boolean     NOT NULL,
  ind_g_mono_padrao       boolean     NOT NULL,
  ind_g_mono_reten        boolean     NOT NULL,
  ind_g_mono_ret          boolean     NOT NULL,
  ind_g_mono_dif          boolean     NOT NULL,
  ind_gp_bio_diferenca    boolean     NOT NULL,
  ind_g_estorno_cred      boolean     NOT NULL,
  tp_rbsn                 smallint    NOT NULL,
  d_ini_vig               date        NOT NULL,
  -- NULÁVEL E SEM DEFAULT: NULL = sem prazo de fim. `ausente-vs-falso.md`.
  d_fim_vig               date,
  ind_nfe                 boolean     NOT NULL,
  ind_nfce                boolean     NOT NULL,
  ind_nfse                boolean     NOT NULL,
  anexo                   text,
  link                    text        NOT NULL,
  search_normalized       text        NOT NULL,
  source_published_at     date        NOT NULL,
  PRIMARY KEY (cst, codigo),
  -- O fim não pode anteceder o início. Satisfeito pelas 164 linhas do arquivo
  -- oficial, inclusive pelas três em que fim = início.
  CONSTRAINT cclass_trib_vigencia_chk CHECK (d_fim_vig IS NULL OR d_fim_vig >= d_ini_vig),
  CONSTRAINT cclass_trib_p_red_ibs_chk CHECK (p_red_ibs >= 0 AND p_red_ibs <= 100),
  CONSTRAINT cclass_trib_p_red_cbs_chk CHECK (p_red_cbs >= 0 AND p_red_cbs <= 100)
);

COMMENT ON TABLE cclass_trib IS
  'cClassTrib — tabela de REFERÊNCIA carregada do arquivo oficial cClassTrib do Portal DF-e SVRS. A chave é o PAR (cst, codigo): um cClassTrib só é válido dentro do seu CST, e o par incompatível é rejeitado pela SEFAZ. O código é único nesta publicação, mas isso é propriedade do dado, não do domínio — por isso não é a chave.';
COMMENT ON COLUMN cclass_trib.p_red_ibs IS
  'Percentual de REDUÇÃO da alíquota do IBS, inteiro em [0, 100]: efetiva = original × (1 − p_red_ibs/100). Zero é apurado ("sem redução"), não ausência. Atributo do CÓDIGO, não escolha do emitente.';
COMMENT ON COLUMN cclass_trib.p_red_cbs IS
  'Percentual de REDUÇÃO da alíquota da CBS, inteiro em [0, 100]. Separado do IBS de propósito: o código 200025 (ProUni) tem 60 no IBS e 100 na CBS.';
COMMENT ON COLUMN cclass_trib.d_fim_vig IS
  'Fim da vigência do código. NULL = sem prazo de fim (161 das 164). Os três preenchidos — 220001/220002/220003 — têm fim IGUAL ao início, como o arquivo oficial traz.';
COMMENT ON COLUMN cclass_trib.source_published_at IS
  'Data de publicação do arquivo oficial de onde esta linha veio. NÃO é vigência. `select distinct source_published_at` responde "qual publicação o sistema tem carregada".';

-- ─────────────────────────────────────────────────────────────────────────
-- 3. Índices — busca por código e por nome, padrão do `ncm_codes`
-- ─────────────────────────────────────────────────────────────────────────
-- `pg_trgm` já está instalada (os três índices GIN de `ncm_codes` a usam).
CREATE INDEX IF NOT EXISTS idx_cclass_trib_cst ON cclass_trib (cst);
CREATE INDEX IF NOT EXISTS idx_cclass_trib_codigo ON cclass_trib (codigo);
CREATE INDEX IF NOT EXISTS idx_cclass_trib_normalized_trgm
  ON cclass_trib USING gin (search_normalized gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_cst_ibs_cbs_normalized_trgm
  ON cst_ibs_cbs USING gin (search_normalized gin_trgm_ops);

-- ─────────────────────────────────────────────────────────────────────────
-- 4. RLS — leitura pública, exatamente o padrão de `ncm_codes`
-- ─────────────────────────────────────────────────────────────────────────
-- Medido em `pg_policy`: `ncm_read`, cmd = SELECT, roles = public, USING (true).
-- São tabelas de referência publicadas pelo fisco; não há dado de tenant nelas.
-- Escrita fica de fora de propósito: a carga é migração, não é operação do app.
ALTER TABLE cst_ibs_cbs ENABLE ROW LEVEL SECURITY;
ALTER TABLE cclass_trib ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS cst_ibs_cbs_read ON cst_ibs_cbs;
CREATE POLICY cst_ibs_cbs_read ON cst_ibs_cbs FOR SELECT USING (true);

DROP POLICY IF EXISTS cclass_trib_read ON cclass_trib;
CREATE POLICY cclass_trib_read ON cclass_trib FOR SELECT USING (true);

-- ─────────────────────────────────────────────────────────────────────────
-- 5. CARGA — 18 + 164 linhas do arquivo oficial de 2026-06-22
-- ─────────────────────────────────────────────────────────────────────────
-- Idempotente por ON CONFLICT: reaplicar a migração atualiza no lugar, não
-- duplica. Uma publicação NOVA entra como migração NOVA, com outro
-- `source_published_at` — este arquivo nunca é editado para "atualizar a tabela".

INSERT INTO cst_ibs_cbs (cst, descricao, ind_gibscbs, ind_gibscbs_mono, ind_gred, ind_gdif, ind_gtransf_cred, ind_gcred_pres_ibszfm, ind_gajuste_compet, ind_redutor_bc, search_normalized, source_published_at) VALUES
