  descricao = EXCLUDED.descricao,
  ind_gibscbs = EXCLUDED.ind_gibscbs,
  ind_gibscbs_mono = EXCLUDED.ind_gibscbs_mono,
  ind_gred = EXCLUDED.ind_gred,
  ind_gdif = EXCLUDED.ind_gdif,
  ind_gtransf_cred = EXCLUDED.ind_gtransf_cred,
  ind_gcred_pres_ibszfm = EXCLUDED.ind_gcred_pres_ibszfm,
  ind_gajuste_compet = EXCLUDED.ind_gajuste_compet,
  ind_redutor_bc = EXCLUDED.ind_redutor_bc,
  search_normalized = EXCLUDED.search_normalized,
  source_published_at = EXCLUDED.source_published_at;

INSERT INTO cclass_trib (cst, codigo, nome, descricao, lc_redacao, lc_214_25, regulamento_cbs, regulamento_ibs, tipo_aliquota, p_red_ibs, p_red_cbs, ind_g_trib_regular, ind_g_cred_pres_oper, ind_g_mono_padrao, ind_g_mono_reten, ind_g_mono_ret, ind_g_mono_dif, ind_gp_bio_diferenca, ind_g_estorno_cred, tp_rbsn, d_ini_vig, d_fim_vig, ind_nfe, ind_nfce, ind_nfse, anexo, link, search_normalized, source_published_at) VALUES
